#include <vector>
#include <stdexcept>
#include <omp.h>

void axpy(double alpha, std::vector<double> const& x, std::vector<double> const& y, std::vector<double> &z) {
    const std::size_t n = x.size();
    if (y.size() != n) throw std::invalid_argument("axpy: x and y must have the same length");

    // Ensure output has correct size.
    z.resize(n);

    // Parallelize the independent element-wise computation.
    #pragma omp parallel for schedule(static)
    for (std::size_t i = 0; i < n; ++i) {
        z[i] = alpha * x[i] + y[i];
    }
}
